package com.wandertrace.exception;
import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NotFoundException.class)ResponseEntity<Map<String,Object>> missing(NotFoundException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"Resource not found",r);}@ExceptionHandler({AccessDeniedException.class,org.springframework.security.access.AccessDeniedException.class})ResponseEntity<Map<String,Object>> denied(Exception e,HttpServletRequest r){return error(HttpStatus.FORBIDDEN,"Access denied",r);}@ExceptionHandler(MaxUploadExceededException.class)ResponseEntity<Map<String,Object>> tooLarge(MaxUploadExceededException e,HttpServletRequest r){return error(HttpStatus.PAYLOAD_TOO_LARGE,e.getMessage(),r);}@ExceptionHandler({IllegalArgumentException.class})ResponseEntity<Map<String,Object>> badRequest(Exception e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,e.getMessage(),r);}@ExceptionHandler(DuplicateResourceException.class)ResponseEntity<Map<String,Object>> duplicate(DuplicateResourceException e,HttpServletRequest r){return error(HttpStatus.CONFLICT,e.getMessage(),r);}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<Map<String,Object>> invalid(MethodArgumentNotValidException e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"Validation failed",r);}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,Object>> unexpected(Exception e,HttpServletRequest r){return error(HttpStatus.INTERNAL_SERVER_ERROR,"Something went wrong",r);}private ResponseEntity<Map<String,Object>> error(HttpStatus s,String m,HttpServletRequest r){Map<String,Object>b=new LinkedHashMap<>();b.put("success",false);b.put("data",null);b.put("message",m);b.put("timestamp",Instant.now().toString());b.put("path",r.getRequestURI());return ResponseEntity.status(s).body(b);}}
